# ── 合并脚本 ──
with open('../public-library.json','r',encoding='utf-8') as f:
    data = json.load(f)

subjects = data['subjects']

def add_to(sub_id, new_cards):
    for s in subjects:
        if s['id'] == sub_id:
            existing_titles = {c['title'] for c in s['cards']}
            for c in new_cards:
                if c['title'] not in existing_titles:
                    s['cards'].append(c)
            s['cardCount'] = len(s['cards'])
            s['chapters'] = list(dict.fromkeys(c['chapter'] for c in s['cards']))
            return len(s['cards'])

r1 = add_to('pub-xwx', xw_new)
r2 = add_to('pub-cbx', cb_new)
r3 = add_to('pub-xwls', xwls_new)
r4 = add_to('pub-xwsw', xwsw_new)

data['_version'] = 3
data['_description'] = '十三大热门考研专业课知识卡片，每科100+张，总计700+张'

with open('../public-library.json','w',encoding='utf-8') as f:
    json.dump(data, f, ensure_ascii=False)

total = sum(len(s['cards']) for s in data['subjects'])
new_total = r1+r2+r3+r4
print(f"新闻学: {r1}, 传播学: {r2}, 新闻史: {r3}, 新闻实务: {r4}")
print(f"新增: {new_total}, 总计: {total}")
for s in data['subjects']:
    flag = " ✔" if len(s['cards'])>=100 else f" ({100-len(s['cards'])} short)"
    print(f"  {s['name']:12s} {len(s['cards']):3d} cards {'' if len(s['cards'])>=100 else flag}")
